(()=>{(()=>{let r=document.querySelector(".legal-toc nav");if(!r||!("IntersectionObserver"in window))return;let t=[...r.querySelectorAll('a[href^="#"]')],n=t.map(e=>document.getElementById(e.hash.slice(1))),c=new IntersectionObserver(e=>{for(let o of e){if(!o.isIntersecting)continue;t.forEach(s=>s.removeAttribute("aria-current"));let i=n.indexOf(o.target);i!==-1&&t[i].setAttribute("aria-current","location")}},{rootMargin:"-18% 0px -65% 0px",threshold:0});n.filter(Boolean).forEach(e=>c.observe(e))})();})();
